import React, { useRef, useState } from "react";
import emailjs from "@emailjs/browser";

const Subscribe = () => {
  const [subscribeDisabled, setSubscribeDisabled] = useState(true);
  const [showError, setShowError] = useState(false);
  const [emailStatusMessage, setEmailStatusMessage] = useState("");
  const form = useRef();

  const sendEmail = (e) => {
    e.preventDefault();

    if (subscribeDisabled) {
      setShowError(true);
      return;
    } else {
      setShowError(false);
      setEmailStatusMessage("Subscribing..");
      emailjs
        .sendForm(
          process.env.REACT_APP_EMAILJS_SERVICE_ID,
          process.env.REACT_APP_EMAILJS_TEMPLATE_ID,
          form.current,
          {
            publicKey: process.env.REACT_APP_EMAILJS_PUBLIC_KEY,
          }
        )
        .then(
          () => {
            setEmailStatusMessage(
              "Thank you for subscribing! Please look for email from idealaunchlab@gmail.com"
            );
          },
          (error) => {
            setEmailStatusMessage(
              "Something went wrong!! Please email idealaunchlab@gmail.com to sign up."
            );
          }
        );
    }
  };
  let handleOnChange = (data) => {
    var email = data.target.value;
    // don't remember from where i copied this code, but this works.
    let re =
      /^(([^<>()\[\]\\.,;:\s@"]+(\.[^<>()\[\]\\.,;:\s@"]+)*)|(".+"))@((\[[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}\.[0-9]{1,3}])|(([a-zA-Z\-0-9]+\.)+[a-zA-Z]{2,}))$/;

    if (re.test(email)) {
      // this is a valid email address
      // call setState({email: email}) to update the email
      // or update the data in redux store.
      setSubscribeDisabled(false);
    } else {
      // invalid email, maybe show an error to the user.
      setSubscribeDisabled(true);
    }
  };
  return (
    <div className="subscription-form">
      {emailStatusMessage == "" ? (
        <form ref={form} onSubmit={sendEmail}>
          <div className="subscribe-form">
            <div className="row">
              <div className={"col-md-5"}>
                <div className="field form-widgets">
                  <input
                    type="email"
                    className="form-control"
                    name="reply_to"
                    id="reply_to"
                    placeholder="Enter email"
                    onChange={(e) => handleOnChange(e)}
                  />
                </div>
              </div>
              <div className={"col-md-4"}>
                <div className="field form-widgets">
                  <input
                    className="btn btn-custom btn-small"
                    type="submit"
                    id="button"
                    value="Signup for updates"
                  />
                </div>
              </div>
            </div>
          </div>
          <div>
            <span style={{color: "red", opacity: showError ? 1 : 0 }}>
              Please enter a valid email
            </span>
          </div>
        </form>
      ) : (
        emailStatusMessage
      )}
    </div>
  );
};

export default Subscribe;
